int MenuCommand(unsigned char menu, unsigned item) { return (static_cast<int>(menu) << 8) | (item & 0xFF); }
void Callback(const OsGuiCallbackInfo& info, int type, int subtype, int code)
{ if (info.function) { OsGuiCallbackParams params{type,subtype,code,info.userParam}; info.function(&params); } }
void EraseArrayItem(auto& array, unsigned index)
{ for (unsigned i=index+1;i<array.Count();++i) array[i-1]=array[i]; array.SetCount(array.Count()-1); }
