COsMenu::COsMenu() : COsMenu(0, "") {}
COsMenu::COsMenu(unsigned char id,const char* title):mID(id),mMenuHandle(CreatePopupMenu()),mTitle{},mHotkeys(8){strncpy_s(mTitle,title?title:"",_TRUNCATE);}
COsMenu::~COsMenu(){if(mMenuHandle)DestroyMenu(mMenuHandle);mMenuHandle=nullptr;}
void COsMenu::Clear(){while(GetMenuItemCount(mMenuHandle)>0)DeleteMenu(mMenuHandle,0,MF_BYPOSITION);mHotkeys.SetCount(0);}
void COsMenu::RemoveItem(int pos){if(pos>=0)DeleteMenu(mMenuHandle,pos,MF_BYPOSITION);RemoveHotkey(pos);}
int COsMenu::GetNumItems()const{return mMenuHandle?GetMenuItemCount(mMenuHandle):0;}
int COsMenu::GetHotkey(unsigned pos,OsGuiMenuHotkey* out)const{if(!out||pos>=mHotkeys.Count())return 0;*out=mHotkeys[pos];return out->keyID!=0;}
void COsMenu::AddHotkey(int pos){if(pos<0)return;while(mHotkeys.Count()<=static_cast<unsigned>(pos))mHotkeys.Add({0,0});}
void COsMenu::RemoveHotkey(int pos){if(pos>=0&&static_cast<unsigned>(pos)<mHotkeys.Count())EraseArrayItem(mHotkeys,pos);}
void COsMenu::AppendHotkeyText(char* text,const OsGuiMenuHotkey& hotkey)const{if(!text)return;char key[64]{};OsGuiGetHotkeyText(hotkey,key,sizeof(key));if(*key){strcat_s(text,256,"\t");strcat_s(text,256,key);}}
void COsMenu::AddTextItem(unsigned pos,const char* text,OsGuiMenuHotkey* hotkey){MENUITEMINFOA item{sizeof(item)};item.fMask=MIIM_ID|MIIM_STRING;item.wID=MenuCommand(mID,pos);item.dwTypeData=const_cast<char*>(text?text:"");InsertMenuItemA(mMenuHandle,pos,TRUE,&item);AddHotkey(pos);if(hotkey)mHotkeys[pos]=*hotkey;}
void COsMenu::AddSubMenu(int pos,const char* title,COsMenu* menu){if(!menu)return;MENUITEMINFOA item{sizeof(item)};item.fMask=MIIM_SUBMENU|MIIM_STRING;item.hSubMenu=menu->mMenuHandle;item.dwTypeData=const_cast<char*>(title?title:"");InsertMenuItemA(mMenuHandle,pos,TRUE,&item);}
void COsMenu::AddSeparator(int pos){InsertMenuA(mMenuHandle,pos,MF_BYPOSITION|MF_SEPARATOR,0,nullptr);}
void COsMenu::EnableItem(unsigned pos,int value){EnableMenuItem(mMenuHandle,pos,MF_BYPOSITION|(value?MF_ENABLED:MF_GRAYED));}
void COsMenu::CheckItem(unsigned pos,int value){CheckMenuItem(mMenuHandle,pos,MF_BYPOSITION|(value?MF_CHECKED:MF_UNCHECKED));}
void COsMenu::SetItemText(unsigned pos,const char* text){MENUITEMINFOA item{sizeof(item)};item.fMask=MIIM_STRING;item.dwTypeData=const_cast<char*>(text?text:"");SetMenuItemInfoA(mMenuHandle,pos,TRUE,&item);}

COsMenuBar::COsMenuBar(HWND window):mMenus(4),mWindowHandle(window),mMenuBarHandle(CreateMenu()),mAccelerators(nullptr){}
COsMenuBar::~COsMenuBar(){if(mAccelerators)DestroyAcceleratorTable(mAccelerators);if(mMenuBarHandle)DestroyMenu(mMenuBarHandle);}
void COsMenuBar::Set(TSGrowableArray<COsMenu*>* menus){mMenus.SetCount(0);while(GetMenuItemCount(mMenuBarHandle)>0)DeleteMenu(mMenuBarHandle,0,MF_BYPOSITION);if(menus)for(unsigned i=0;i<menus->Count();++i){COsMenu* menu=(*menus)[i];mMenus.Add(menu);AppendMenuA(mMenuBarHandle,MF_POPUP,reinterpret_cast<UINT_PTR>(menu->mMenuHandle),menu->mTitle);}SetMenu(mWindowHandle,mMenuBarHandle);UpdateAccelerators();Refresh();}
void COsMenuBar::UpdateAccelerators(){if(mAccelerators){DestroyAcceleratorTable(mAccelerators);mAccelerators=nullptr;}std::vector<ACCEL> entries;for(unsigned m=0;m<mMenus.Count();++m)for(unsigned i=0;i<mMenus[m]->mHotkeys.Count();++i){auto key=mMenus[m]->mHotkeys[i];if(!key.keyID)continue;ACCEL a{};a.cmd=static_cast<WORD>(MenuCommand(mMenus[m]->mID,i));a.key=static_cast<WORD>(key.keyID);a.fVirt=FVIRTKEY|static_cast<BYTE>(key.modKeyID);entries.push_back(a);}if(!entries.empty())mAccelerators=CreateAcceleratorTableA(entries.data(),static_cast<int>(entries.size()));}
void COsMenuBar::Refresh(){if(mWindowHandle)DrawMenuBar(mWindowHandle);}

