void COsControl::SetTooltip(char* text)
{
    HWND tips = nullptr;
    HWND owner = nullptr;
    if (mDialog) {
        tips = static_cast<HWND>(mDialog->GetTooltips());
        owner = mDialog->mHandle;
    } else {
        tips = sGetGlobalTips();
        owner = mHandle ? GetParent(mHandle) : nullptr;
    }
    if (!tips || !mHandle)
        return;

    TOOLINFOA tool{};
    tool.cbSize = sizeof(tool);
    tool.uFlags = TTF_IDISHWND | TTF_SUBCLASS;
    tool.hwnd = owner;
    tool.uId = reinterpret_cast<UINT_PTR>(mHandle);
    tool.hinst = s_instance;
    tool.lpszText = text;
    if (!SendMessageA(tips, TTM_ADDTOOLA, 0, reinterpret_cast<LPARAM>(&tool)))
        OutputDebugStringA("Warning: COsControl::SetTooltip - TTM_ADDTOOL failed\n");
}
