int COsTreeView::OnMouseDown(){return 0;}int COsTreeView::OnMouseUp(){if(mDragging)OnEndDrag();return 0;}OsGuiTreeItem COsTreeView::FindItemUnderCursor(){POINT p{};GetCursorPos(&p);ScreenToClient(mHandle,&p);TVHITTESTINFO h{};h.pt=p;return TreeView_HitTest(mHandle,&h);}int COsTreeView::OnReturn(){return SendEvent(1,reinterpret_cast<intptr_t>(GetSelectedItem())&0x7FFFFFFF);}int COsTreeView::OnEscape(){if(mDragging){OnEndDrag();return 1;}return 0;}int COsTreeView::OnNotify(int code,void*p){if(code==TVN_ITEMEXPANDEDA)OnExpandedItem(reinterpret_cast<NMTREEVIEWA*>(p)->itemNew.hItem);else if(code==TVN_DELETEITEMA)OnDeleteItem(reinterpret_cast<NMTREEVIEWA*>(p)->itemOld.hItem);return 0;}HWND COsTreeView::GetEditControl()const{return TreeView_GetEditControl(mHandle);}bool COsTreeView::IsHandleFromControl(HWND h)const{return COsControl::IsHandleFromControl(h)||h==GetEditControl();}
