void COsTreeView::OnBeginDrag(OsGuiTreeItem i,int x,int y){mDragging=1;mDragInfo.dragItem=i;mDragInfo.targX=x;mDragInfo.targY=y;CreateDragImage(i);SetCapture(mHandle);}void COsTreeView::OnMouseMove(int x,int y){if(!mDragging)return;mDragInfo.targX=x;mDragInfo.targY=y;mDragInfo.targItem=FindItemUnderCursor();POINT p{x,y};ClientToScreen(mHandle,&p);ImageList_DragMove(p.x,p.y);SetDropTarget(mDragInfo.targItem);}void COsTreeView::SetDropTarget(OsGuiTreeItem i){TreeView_SelectDropTarget(mHandle,reinterpret_cast<HTREEITEM>(i));mDragInfo.targItem=i;}void COsTreeView::SetInsertionMark(OsGuiTreeItem i,int after){TreeView_SetInsertMark(mHandle,reinterpret_cast<HTREEITEM>(i),after);}void COsTreeView::OnEndDrag(){RunDragHandler();SetDropTarget(nullptr);DestroyDragImage();ReleaseCapture();mDragging=0;}int COsTreeView::OnBeginEdit(OsGuiTreeItem i){return mCanEditFunc?!mCanEditFunc(i,mCanEditParam):0;}int COsTreeView::OnEndEdit(OsGuiTreeItem i,char*t){if(t)SetItemText(i,t);return t!=nullptr;}void COsTreeView::SetTextLimit(int n){mTextLimit=n;}void COsTreeView::EnableFilters(int v){mFiltersEnabled=v;}void COsTreeView::SetFilter(unsigned f,int v){if(v)mFilters|=f;else mFilters&=~f;}bool COsTreeView::IsCharacterAllowed(char c)const{return!mFiltersEnabled||!(mFilters&1)||c>=' ';}void COsTreeView::SetCanEditFunction(int(__fastcall*f)(void*,void*),void*p){mCanEditFunc=f;mCanEditParam=p;}void COsTreeView::SetExpandFunction(void(__fastcall*f)(void*,void*),void*p){mExpandFunc=f;mExpandParam=p;}void COsTreeView::OnDeleteItem(OsGuiTreeItem i){if(auto*p=GetParams(i)){p->used=0;p->user=nullptr;}}

