void OsGuiMenuSelect(unsigned char menu,unsigned char item){Callback(s_menuCallback,menu,item,MenuCommand(menu,item));}
void OsGuiInitialize(){INITCOMMONCONTROLSEX controls{sizeof(controls),ICC_WIN95_CLASSES|ICC_BAR_CLASSES|ICC_TREEVIEW_CLASSES|ICC_LISTVIEW_CLASSES};InitCommonControlsEx(&controls);}
void OsGuiDestroy(){s_menuCallback={};s_idleCallback={};s_gxWindow=nullptr;}
void OsGuiSetApplicationInfo(HINSTANCE instance){s_instance=instance;} void OsGuiSetMenuCommandCallback(OsGuiCallback f,void*p){s_menuCallback={f,p};} void OsGuiSetIdleCallback(OsGuiCallback f,void*p){s_idleCallback={f,p};}
int OsGuiProcessMessage(MSG* msg){if(!msg)return 0;TranslateMessage(msg);DispatchMessageA(msg);if(s_idleCallback.function)Callback(s_idleCallback,0,0,0);return 1;} void OsGuiEnableTooltips(int v){s_tooltipsEnabled=v!=0;} void OsGuiEnableMenuHotkeys(int v){s_menuHotkeysEnabled=v!=0;}
void OsGuiSetCursor(int cursor){LPCTSTR id=IDC_ARROW;if(cursor==1)id=IDC_IBEAM;else if(cursor==2)id=IDC_WAIT;else if(cursor==3)id=IDC_SIZEWE;else if(cursor==4)id=IDC_SIZENS;::SetCursor(LoadCursor(nullptr,id));} void OsGuiShowCursor(int v){::ShowCursor(v!=0);} void OsGuiGetCursorPosition(int*x,int*y){POINT p{};GetCursorPos(&p);if(x)*x=p.x;if(y)*y=p.y;}
void OsGuiSetWindowTitle(HWND w,const char*t){if(w)SetWindowTextA(w,t?t:"");} void OsGuiSetWindowIcon(HWND w,const char*n){if(!w)return;HICON icon=static_cast<HICON>(LoadImageA(s_instance,n,IMAGE_ICON,0,0,LR_DEFAULTSIZE|LR_LOADFROMFILE));if(icon){SendMessageA(w,WM_SETICON,ICON_BIG,reinterpret_cast<LPARAM>(icon));SendMessageA(w,WM_SETICON,ICON_SMALL,reinterpret_cast<LPARAM>(icon));}}
NTempest::CiRect OsGuiGetWindowRect(HWND w,int client){RECT r{};if(w){if(client){GetClientRect(w,&r);POINT p{r.left,r.top};ClientToScreen(w,&p);OffsetRect(&r,p.x,p.y);}else::GetWindowRect(w,&r);}return{r.left,r.top,r.right,r.bottom};} void OsGuiSetWindowRect(HWND w,const NTempest::CiRect&r){if(w)SetWindowPos(w,nullptr,r.minX,r.minY,r.Width(),r.Height(),SWP_NOZORDER);}
