NTempest::CiRect OsGuiGetWindowRestoredRect(HWND w){WINDOWPLACEMENT p{sizeof(p)};if(w)GetWindowPlacement(w,&p);return{p.rcNormalPosition.left,p.rcNormalPosition.top,p.rcNormalPosition.right,p.rcNormalPosition.bottom};} void OsGuiSetWindowRestoredRect(HWND w,const NTempest::CiRect&r){WINDOWPLACEMENT p{sizeof(p)};if(w&&GetWindowPlacement(w,&p)){p.rcNormalPosition={r.minX,r.minY,r.maxX,r.maxY};SetWindowPlacement(w,&p);}}
