void OsGuiBeep(){MessageBeep(MB_OK);} int OsGuiMessageBox(HWND w,int style,const char*m,const char*t){return MessageBoxA(w,m?m:"",t?t:"",style);} int OsGuiIsModifierKeyDown(unsigned k){return(GetKeyState(static_cast<int>(k))&0x8000)!=0;}
void OsGuiGetHotkeyText(const OsGuiMenuHotkey& h,char*out,unsigned size){if(!out||!size)return;out[0]=0;if(h.modKeyID&FCONTROL)strcat_s(out,size,"Ctrl+");if(h.modKeyID&FSHIFT)strcat_s(out,size,"Shift+");if(h.modKeyID&FALT)strcat_s(out,size,"Alt+");char key[32]{};UINT scan=MapVirtualKeyA(h.keyID,MAPVK_VK_TO_VSC)<<16;GetKeyNameTextA(scan,key,sizeof(key));strcat_s(out,size,key);}
