void sGetHotkeyText(int modifier,int key,char* buffer,unsigned size){OsGuiGetHotkeyText({key,modifier},buffer,size);}int sNCodeToItemCode(int controlType,int notifyCode){return (controlType<<16)|(notifyCode&0xFFFF);}
